use std::{env,fs::File,io::{self,Read,Write}};
const REC:usize=3073;const PIX:usize=3072;const PER:usize=32;
struct M{data:Vec<Vec<u8>>}
fn read_data(dir:&str)->io::Result<Vec<Vec<u8>>>{let mut all=Vec::new();for n in 1..=5{let mut b=Vec::new();let p=format!("{}/data_batch_{}.bin",dir,n);if !std::path::Path::new(&p).exists(){continue}File::open(p)?.read_to_end(&mut b)?;for s in 0..b.len()/REC{let o=s*REC;let mut v=Vec::with_capacity(REC);v.push(b[o]);v.extend_from_slice(&b[o+1..o+REC]);all.push(v)}}Ok(all)}
fn train(dir:&str,out:&str)->io::Result<()>{let all=read_data(dir)?;let mut counts=[0usize;10];let mut keep=Vec::new();for r in all{let c=r[0]as usize;if counts[c]<PER{keep.push(r);counts[c]+=1}}let mut f=File::create(out)?;f.write_all(b"CS01")?;for r in &keep{f.write_all(r)?}println!("saved {} exemplars to {}",keep.len(),out);Ok(())}
fn load(p:&str)->io::Result<M>{let mut b=Vec::new();File::open(p)?.read_to_end(&mut b)?;let mut data=Vec::new();let mut q=4;while q+REC<=b.len(){data.push(b[q..q+REC].to_vec());q+=REC}Ok(M{data})}
fn gen(m:&M,class:usize,seed:usize,out:&str)->io::Result<()>{let pool:Vec<&Vec<u8>>=m.data.iter().filter(|r|r[0]as usize==class).collect();if pool.is_empty(){return Err(io::Error::new(io::ErrorKind::NotFound,"class not in sampler"))}let r=pool[seed%pool.len()];let mut f=File::create(out)?;writeln!(f,"P6\n32 32\n255")?;for i in 0..1024{f.write_all(&[r[1+i],r[1+1024+i],r[1+2048+i]])?}println!("generated class={} exemplar={} output={}",class,seed%pool.len(),out);Ok(())}
fn main()->io::Result<()>{let a:Vec<String>=env::args().collect();match a.get(1).map(String::as_str){Some("train")=>train(&a[2],&a[3]),Some("generate")=>gen(&load(&a[2])?,a[3].parse().unwrap(),a.get(4).and_then(|v|v.parse().ok()).unwrap_or(0),&a[5]),_=>{println!("train <cifar-dir> <model.tlm>\ngenerate <model.tlm> <class 0-9> <seed> <out.ppm>\nclasses: 3=cat, 1=automobile");Ok(())}}}
